 let code=readFileSync(new URL('../'+src,import.meta.url),'utf8').replaceAll("'@/db'","'./db.mjs'").replaceAll("'@/db/schema'","'./schema.mjs'").replaceAll("'@/app/chatgpt-auth'","'./who.mjs'").replaceAll("'./request-context'","'./request.mjs'").replaceAll("'./auth'","'./login.mjs'").replaceAll("'./domain'","'./domain.mjs'").replaceAll("'./study-domain'","'./study-domain.mjs'").replaceAll("'./academic-grid'","'./academic-grid.mjs'").replaceAll("'./class-tools'","'./class-tools.mjs'");
