for(const f of readdirSync(new URL('../drizzle/',import.meta.url)).filter(f=>f.endsWith('.sql')).sort())sqlite.exec(readFileSync(new URL('../drizzle/'+f,import.meta.url),'utf8'));
let conflict=false;
class Statement{constructor(q,p=[]){this.q=q;this.p=p}bind(...p){return new Statement(this.q,p)}async all(){return {results:sqlite.prepare(this.q).all(...this.p),success:true,meta:{}}}async raw(){return sqlite.prepare(this.q).all(...this.p).map(x=>Object.values(x))}async run(){const r=sqlite.prepare(this.q).run(...this.p);return {results:[],success:true,meta:{changes:Number(r.changes)}}}}
globalThis.__d1={prepare:q=>new Statement(q),batch:async queries=>{if(conflict){conflict=false;sqlite.exec('UPDATE classes SET revision=revision+1')}sqlite.exec('BEGIN');try{const out=[];for(const q of queries){out.push(await q.all())}sqlite.exec('COMMIT');return out}catch(e){sqlite.exec('ROLLBACK');throw e}}};
